-- All 67 Florida counties. FIPS = 12 + county code; nal_county_code = FL DOR county number (11-77).
-- RealAuction sites read from the site picker on lake.realtaxdeed.com (2026-10-12).
-- Idempotent: re-running updates platform info but never touches is_active / last_scraped_at.
on conflict (fips) do update set
  county_name = excluded.county_name,
  auction_platform = excluded.auction_platform,
  auction_base_url = excluded.auction_base_url,
  nal_county_code = excluded.nal_county_code,
  notes = excluded.notes;
